mapper.select:
SELECT a.game_level, a.game_wave, NOW() AS now_date_time, b.ins_date AS start_date
FROM game_result_data a LEFT JOIN offline_mode_log b ON a.user_uuid = b.user_uuid
WHERE a.user_uuid = #{user_uuid}
  AND a.game_result = 'Clear'
ORDER BY a.game_level DESC, a.game_wave DESC, b.ins_date DESC
    LIMIT 1;
